import os
from typing import Any, Dict, List, Optional

try:
    from openai import OpenAI
except Exception as exc:  # pragma: no cover
    OpenAI = None
    _import_error = exc


def _get_client() -> "OpenAI":
    if OpenAI is None:
        raise RuntimeError(f"openai client unavailable: {_import_error}")
    return OpenAI(api_key=os.environ["OPENAI_API_KEY"])


def _serialize_record(record: Any) -> str:
    if isinstance(record, str):
        return record
    if isinstance(record, dict):
        items = []
        for key in sorted(record.keys()):
            value = record[key]
            items.append(f"{key}: {value}")
        return "\n".join(items)
    if isinstance(record, list):
        return "\n".join(_serialize_record(item) for item in record)
    return str(record)


def summarize_records(
    records: List[Dict[str, Any]],
    *,
    subject: Optional[str] = None,
    max_tokens: int = 256,
) -> str:
    client = _get_client()
    payload = "\n\n".join(
        f"Record {i + 1}:\n{_serialize_record(record)}" for i, record in enumerate(records)
    )
    prompt = (
        "Summarize the retrieved document records clearly and concisely."
        + (f" Focus on {subject}." if subject else "")
        + "\n\nRecords:\n"
        + payload
    )
    response = client.responses.create(
        model="gpt-5.4-mini",
        input=prompt,
        max_output_tokens=max_tokens,
    )
    return getattr(response, "output_text", "") or ""

